stage_a_raw:
{
  "decisions": [
    {
      "decision": "demand_satisfaction_direction",
      "evidence": "\"needs a specific amount to fulfill the demands\" / \"ensure that every warehouse has the supplies it needs\"",
      "options": [
        "final amount >= need (surplus allowed)",
        "final amount == need (exact match required)"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "final amount >= need (surplus allowed)"
    },
    {
      "decision": "outflow_cap_from_initial_stock",
      "evidence": "\"Each warehouse starts with a certain amount of supplies\"",
      "options": [
        "include outflow <= initial stock per warehouse",
        "omit outflow cap (only net balance enforced)"
      ],
      "plausibility": [
        0.55,
        0.45
      ],
      "majority_option": "omit outflow cap (only net balance enforced)"
    },
    {
      "decision": "flow_variable_domain",
      "evidence": "none (units of supplies; text never says divisible or whole)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "cost_matrix_orientation",
      "evidence": "\"Moving supplies from/to Warehouse 1: To Warehouse 2 costs 36\" / \"Moving supplies from/to Warehouse 2: To Warehouse 1 costs 28\"",
      "options": [
        "cost[i][j] = cost to move from i to j (row = origin)",
        "cost[i][j] = cost to move from j to i (row = destination)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "cost[i][j] = cost to move from i to j (row = origin)"
    },
    {
      "decision": "objective_quantity",
      "evidence": "\"What is the minimum cost needed to relocate the supplies\"",
      "options": [
        "minimize total transportation cost sum cost*x",
        "minimize total units moved (ignore costs)"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "minimize total transportation cost sum cost*x"
    },
    {
      "decision": "balance_constraint_form",
      "evidence": "\"move supplies from one warehouse to another to meet the demand\"",
      "options": [
        "inflow - outflow >= need - has (net requirement)",
        "has + inflow - outflow >= need (final stock requirement)"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "has + inflow - outflow >= need (final stock requirement)"
    }
  ]
}
